#import "SLTitleViewController.h"
#import "SLReaderViewController.h"
#import "SLDownloadManager.h"
#import "SLStore.h"
#import "SLAPI.h"
#import "SLTheme.h"
@implementation SLTitleViewController
- (id)initWithTitle:(NSDictionary *)info { if ((self=[super initWithStyle:UITableViewStyleGrouped])) { NSMutableDictionary *normalized=[NSMutableDictionary dictionaryWithDictionary:info?:[NSDictionary dictionary]];if(![normalized objectForKey:@"site"]&&[normalized objectForKey:@"site_id"])[normalized setObject:[normalized objectForKey:@"site_id"] forKey:@"site"];_titleInfo=[normalized copy]; _chapters=[[NSMutableArray alloc] init]; self.title=[info objectForKey:@"_display"] ?: @"Тайтл"; } return self; }
- (void)viewDidLoad { [super viewDidLoad]; self.tableView.rowHeight=54;self.tableView.backgroundColor=[SLTheme backgroundColor]; self.navigationItem.rightBarButtonItems=[NSArray arrayWithObjects:[[[UIBarButtonItem alloc]initWithTitle:@"↓" style:UIBarButtonItemStylePlain target:self action:@selector(downloadAll)]autorelease],[[[UIBarButtonItem alloc] initWithTitle:@"☆" style:UIBarButtonItemStylePlain target:self action:@selector(toggleFavorite)] autorelease],nil]; UILabel *head=[[[UILabel alloc] initWithFrame:CGRectMake(12,0,self.view.bounds.size.width-24,72)] autorelease]; head.numberOfLines=3; head.text=[NSString stringWithFormat:@"%@\n%@", [_titleInfo objectForKey:@"eng_name"] ?: @"", [_titleInfo objectForKey:@"slug_url"] ?: @""]; self.tableView.tableHeaderView=head; [self loadDetails]; [self loadChapters]; }
- (void)downloadAll { for(NSDictionary *c in _chapters)[[SLDownloadManager shared]downloadChapter:c slug:[self slug] title:[_titleInfo objectForKey:@"rus_name"] site:[[_titleInfo objectForKey:@"site"]integerValue]]; UIAlertView *a=[[[UIAlertView alloc]initWithTitle:@"Загрузки" message:@"Загрузка глав поставлена в очередь." delegate:nil cancelButtonTitle:@"OK" otherButtonTitles:nil]autorelease];[a show]; }
- (NSString *)slug { return [_titleInfo objectForKey:@"slug_url"] ?: [[_titleInfo objectForKey:@"id"] description]; }
- (void)toggleFavorite { [SLStore toggleFavorite:_titleInfo];BOOL on=[SLStore isFavorite:_titleInfo];((UIBarButtonItem *)[self.navigationItem.rightBarButtonItems lastObject]).title=on?@"★":@"☆"; }
- (void)loadDetails { [[SLAPI shared]details:[self slug] site:[[_titleInfo objectForKey:@"site"]integerValue] completion:^(id root,NSError *err){NSDictionary *d=[root objectForKey:@"data"];if(![d isKindOfClass:[NSDictionary class]])return;NSString *summary=[d objectForKey:@"summary"]?:[d objectForKey:@"description"];if([summary isKindOfClass:[NSString class]]&&[summary length]){UILabel *head=[[[UILabel alloc]initWithFrame:CGRectMake(12,0,self.view.bounds.size.width-24,120)]autorelease];head.numberOfLines=0;head.font=[UIFont systemFontOfSize:13];head.text=[NSString stringWithFormat:@"%@\n\n%@",[_titleInfo objectForKey:@"eng_name"]?:@"",summary];[head sizeToFit];CGRect f=head.frame;f.size.width=self.view.bounds.size.width-24;f.size.height=MAX(100,f.size.height+20);head.frame=f;self.tableView.tableHeaderView=head;}}]; }
- (void)loadChapters { [[SLAPI shared]chapters:[self slug] site:[[_titleInfo objectForKey:@"site"]integerValue] completion:^(id root,NSError *err){NSArray *rows=[root isKindOfClass:[NSDictionary class]]?[root objectForKey:@"data"]:nil;[_chapters removeAllObjects];if([rows isKindOfClass:[NSArray class]])for(NSDictionary *row in rows){NSMutableDictionary *chapter=[NSMutableDictionary dictionaryWithDictionary:row];[chapter setObject:[_titleInfo objectForKey:@"site"]?:@2 forKey:@"site"];[_chapters addObject:chapter];}if(![_chapters count])for(NSDictionary *download in [[SLDownloadManager shared]downloads])if([[download objectForKey:@"slug"]isEqualToString:[self slug]]){NSDictionary *chapter=[download objectForKey:@"chapter"];if(chapter)[_chapters addObject:chapter];}[_chapters sortUsingComparator:^NSComparisonResult(id a,id b){double at=[[a objectForKey:@"volume"]doubleValue],bt=[[b objectForKey:@"volume"]doubleValue];if(at<bt)return NSOrderedAscending;if(at>bt)return NSOrderedDescending;double av=[[a objectForKey:@"number"]doubleValue],bv=[[b objectForKey:@"number"]doubleValue];if(av<bv)return NSOrderedAscending;if(av>bv)return NSOrderedDescending;return NSOrderedSame;}];[self.tableView reloadData];if(err){UIAlertView *a=[[[UIAlertView alloc]initWithTitle:@"Slashlib" message:[err localizedDescription] delegate:nil cancelButtonTitle:@"OK" otherButtonTitles:nil]autorelease];[a show];}}]; }
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s { return [_chapters count]; }
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)p { static NSString *i=@"Chapter"; UITableViewCell *c=[t dequeueReusableCellWithIdentifier:i]; if(!c)c=[[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:i]autorelease]; NSDictionary *d=[_chapters objectAtIndex:p.row]; c.textLabel.text=[NSString stringWithFormat:@"Том %@ · Глава %@", [d objectForKey:@"volume"]?:@"?", [d objectForKey:@"number"]?:@"?"]; c.detailTextLabel.text=[d objectForKey:@"name"];if([[SLDownloadManager shared]downloadedChapterForSlug:[self slug] chapterID:[d objectForKey:@"id"]])c.detailTextLabel.text=[NSString stringWithFormat:@"%@ · скачано",c.detailTextLabel.text?:@""]; c.textLabel.textColor=[SLTheme textColor];c.detailTextLabel.textColor=[SLTheme textColor];c.backgroundColor=[SLTheme backgroundColor];c.accessoryType=UITableViewCellAccessoryDisclosureIndicator; return c; }
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)p { [t deselectRowAtIndexPath:p animated:YES];NSDictionary *chapter=[_chapters objectAtIndex:p.row];SLReaderViewController *v=[[[SLReaderViewController alloc]initWithSlug:[self slug] chapter:chapter titleInfo:_titleInfo]autorelease];[self.navigationController pushViewController:v animated:YES];[SLStore addHistory:_titleInfo chapter:chapter]; }
- (void)dealloc { [_titleInfo release]; [_chapters release]; [_summaryLabel release]; [super dealloc]; }
@end
